/* Does in the browser what font-page/serve.py does on a server. Generated by export_pages.py. */
const BASE = new URL(self.registration.scope).pathname;          // e.g. /geist-proofer/
const BLOB = "https://k2mkucxia43oc7fa.public.blob.vercel-storage.com";
const LOADER = "\n;(function(){if(window.__pgAddon)return;window.__pgAddon=1;import('" + BASE + "addon/playground.js')})();\n";
let MAP = null;
const map = () => MAP || (MAP = fetch(BASE + 'map.json', { cache: 'no-cache' }).then(r => r.json()));

self.addEventListener('install', () => self.skipWaiting());
self.addEventListener('activate', e => e.waitUntil(self.clients.claim()));

self.addEventListener('fetch', e => {
  const u = new URL(e.request.url);
  if (u.origin !== location.origin) return;                       // videos, anything external
  // the page asks for root paths (/vc-ap-…, /_blob/…) and for paths under BASE
  const path = u.pathname.startsWith(BASE) ? '/' + u.pathname.slice(BASE.length) : u.pathname;
  if (u.pathname.startsWith(BASE) && /^\/(sw\.js|map\.json|m\/|README)/.test(path)) return;
  e.respondWith(handle(e.request, path, u.search));
});

const redirect = to => new Response(null, { status: 302, headers: { Location: to } });

async function handle(req, path, search) {
  if (req.method === 'POST') return new Response(null, { status: 204 });   // analytics beacons
  if (path === '/' || path === '/index.html') return redirect(BASE + 'font' + search);
  if (path.startsWith('/addon/')) return fetch(BASE + path.slice(1), { cache: 'no-cache' });   // always the published version
  if (path.startsWith('/_blob/') && /\.(mp4|webm|mov)$/.test(path)) return redirect(BLOB + path.slice(6) + search);
  let url = path + search;
  if (path.endsWith('/_next/image')) {                             // serve the original, not an optimized copy
    const src = new URLSearchParams(search).get('url') || '';
    if (src.startsWith('/_blob/')) url = src;
  }
  const m = await map();
  const hit = m[url] || m[url.split('?')[0]];
  if (!hit) {
    if (url.startsWith('/_blob/')) return redirect(BLOB + url.slice(6));
    if (req.mode === 'navigate') return redirect('https://vercel.com' + path + search);   // links off the page go to the real site
    return new Response('not part of the clone', { status: 404, headers: { 'Content-Type': 'text/plain' } });
  }
  const r = await fetch(BASE + 'm/' + hit[0]);
  if (!r.ok) return r;
  const headers = { 'Content-Type': hit[1] };
  if (/javascript/.test(hit[1])) return new Response(await r.text() + LOADER, { headers });
  return new Response(r.body, { headers });
}
